// Source: pannable-chart
//
// Self-contained: every local import is inlined below. Requires only d3, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useEffect, useMemo, useRef } from 'react';
import * as d3 from 'd3';

// ---- inlined from Axis ----
type Tick = { value: string; offset: number };

function AxisBottom({
  ticks,
  height,
  width
}: {
  ticks: Tick[];
  height: number;
  width: number;
}) {
  return (
    <g className="axis" transform={`translate(0,${height})`}>
      <line x1={0} x2={width} y1={0} y2={0} />
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(${offset},0)`}>
          <line y1={0} y2={5} />
          <text y={18} textAnchor="middle">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

function AxisLeft({ ticks, width }: { ticks: Tick[]; width: number }) {
  return (
    <g className="axis">
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(0,${offset})`}>
          <line className="grid" x1={0} x2={width} y1={0} y2={0} />
          <text x={-10} dy="0.32em" textAnchor="end">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

// ---- inlined from pannableChart ----
type ClosePrice = { date: Date; close: number };

/** mulberry32: a fixed seed keeps the walk identical across reloads. */
function seededRandom(seed: number): () => number {
  let state = seed;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const random = seededRandom(20180102);

/** Box-Muller over the seeded stream: daily log returns are normal and reproducible. */
function normal(): number {
  return Math.sqrt(-2 * Math.log(1 - random())) * Math.cos(2 * Math.PI * random());
}

const START = Date.UTC(2018, 0, 1);
const DAYS = 1826; // 2018-01-01 through 2022-12-31
const DRIFT = 0.0006;
const VOLATILITY = 0.015;

/** Synthetic daily closing prices: a weekday-only geometric random walk with upward drift. */
const dailyClose: ClosePrice[] = [];

let price = 42;
for (let day = 0; day < DAYS; day += 1) {
  const date = new Date(START + day * 86400000);
  const weekday = date.getUTCDay();
  if (weekday === 0 || weekday === 6) continue;
  price *= Math.exp(DRIFT + VOLATILITY * normal());
  dailyClose.push({ date, close: Math.round(price * 100) / 100 });
}

const MARGIN = { top: 16, right: 20, bottom: 44, left: 52 };
const PAN_FACTOR = 6; // the drawn chart is six viewports wide, so most of it is off screen
const MONTH_LABEL_PX = 78;

/** One closing price per trading day, in ascending date order. */
export type Data = { date: Date; close: number }[];

export default function PannableChart({
  data = dailyClose,
  width
}: {
  data?: Data;
  width: number;
}) {
  const scrollRef = useRef<HTMLDivElement>(null);
  const height = Math.max(220, Math.round(width * 0.45));
  const totalWidth = width * PAN_FACTOR;
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerTotalWidth = totalWidth - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;

  const x = useMemo(
    () =>
      d3
        .scaleUtc()
        .domain(d3.extent(data, (d) => d.date) as [Date, Date])
        .range([0, innerTotalWidth]),
    [data, innerTotalWidth]
  );

  const y = useMemo(
    () =>
      d3
        .scaleLinear()
        .domain([0, d3.max(data, (d) => d.close) ?? 0])
        .nice(6)
        .range([innerHeight, 0]),
    [data, innerHeight]
  );

  const area = useMemo(
    () =>
      d3
        .area<Data[number]>()
        .curve(d3.curveStep)
        .x((d) => x(d.date))
        .y0(y(0))
        .y1((d) => y(d.close))(data) ?? '',
    [data, x, y]
  );

  const xTicks: Tick[] = useMemo(() => {
    const [start, end] = x.domain();
    const step = Math.max(
      1,
      Math.ceil((MONTH_LABEL_PX * d3.utcMonths(start, end).length) / innerTotalWidth)
    );
    return x
      .ticks(d3.utcMonth.every(step) ?? d3.utcMonth)
      .map((v) => ({ value: d3.utcFormat('%b %Y')(v), offset: x(v) }));
  }, [x, innerTotalWidth]);

  const yTicks: Tick[] = useMemo(
    () => y.ticks(6).map((v) => ({ value: d3.format('$.0f')(v), offset: y(v) })),
    [y]
  );

  // Open on the most recent data, as a scrolled financial chart is expected to.
  useEffect(() => {
    const node = scrollRef.current;
    if (node) node.scrollLeft = node.scrollWidth;
  }, [totalWidth]);

  if (width === 0) return null;

  const caption =
    width >= 560
      ? 'Scroll left for earlier data. Synthetic prices from a seeded generator, not real market data.'
      : 'Scroll left for earlier data.';

  return (
    <div style={{ position: 'relative', width: '100%' }}>
      <div ref={scrollRef} style={{ overflowX: 'scroll' }}>
        <svg
          viewBox={`0 0 ${totalWidth} ${height}`}
          width={totalWidth}
          height={height}
          style={{ display: 'block' }}
          role="img"
          aria-label="Pannable step area chart of five years of daily closing prices, scrollable horizontally. Synthetic data from a seeded generator, not real market prices."
        >
          <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
            <AxisBottom ticks={xTicks} height={innerHeight} width={innerTotalWidth} />
            <path d={area} fill="var(--accent)" fillOpacity={0.7} />
          </g>
        </svg>
      </div>

      {/* Fixed overlay: the vertical axis must stay put while the plot scrolls under it. */}
      <svg
        viewBox={`0 0 ${width} ${height}`}
        width={width}
        height={height}
        style={{ position: 'absolute', top: 0, left: 0, pointerEvents: 'none', zIndex: 1 }}
        aria-hidden="true"
      >
        <rect x={0} y={0} width={MARGIN.left} height={height} fill="var(--panel)" />
        <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
          <AxisLeft ticks={yTicks} width={innerWidth} />
          {/* The nice()d domain maximum lands on the top of the range, so the top tick is y=0. */}
          <text x={3} y={0} dy="0.32em" fill="var(--text)" fontSize={11} fontWeight={600}>
            $ Close
          </text>
        </g>
        <text x={MARGIN.left} y={height - 6} fill="var(--muted)" fontSize={11}>
          {caption}
        </text>
      </svg>
    </div>
  );
}
